export const getNotifCategoryBadgeStyle = (category: NotificationCategory) => {
  switch (category) {
    case 'Guest Activity':
      return 'bg-emerald-50 text-emerald-600 border-emerald-100/80';
    case 'Event Activity':
      return 'bg-slate-100 text-slate-800 border-slate-200';
    case 'Team':
      return 'bg-slate-100 text-slate-800 border-slate-200';
    case 'Billing':
      return 'bg-rose-50 text-rose-600 border-rose-100/80';
    case 'System':
    default:
      return 'bg-slate-100 text-slate-600 border-slate-200/60';
  }
};

export const getNotifCategoryIcon = (category: NotificationCategory, iconType?: string) => {
  if (iconType === 'rsvp') return <UserPlus className="w-4 h-4" />;
  if (iconType === 'upload') return <Upload className="w-4 h-4" />;
  if (iconType === 'comment') return <MessageSquare className="w-4 h-4" />;
  if (iconType === 'approval') return <CheckSquare className="w-4 h-4" />;
  if (iconType === 'live') return <Tv className="w-4 h-4" />;
  if (iconType === 'team') return <Users className="w-4 h-4" />;
  if (iconType === 'billing') return <CreditCard className="w-4 h-4" />;
  if (iconType === 'subscription') return <Zap className="w-4 h-4" />;
  if (iconType === 'storage') return <HardDrive className="w-4 h-4" />;
  if (iconType === 'announcement') return <Sparkles className="w-4 h-4" />;

  switch (category) {
    case 'Guest Activity':
      return <Users className="w-4 h-4" />;
    case 'Event Activity':
      return <Calendar className="w-4 h-4" />;
    case 'Team':
      return <Users className="w-4 h-4" />;
    case 'Billing':
      return <CreditCard className="w-4 h-4" />;
    case 'System':
    default:
      return <Bell className="w-4 h-4" />;
  }
};

