// Simple IndexedDB Utility for saving files persistently across page refreshes
const initKavaMediaDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('KavaMediaDatabase', 2);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains('media')) {
        db.createObjectStore('media');
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveFileToDB = async (key: string, file: File): Promise<string> => {
  try {
    const db = await initKavaMediaDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('media', 'readwrite');
      const store = tx.objectStore('media');
      const request = store.put(file, key);
      request.onsuccess = () => {
        resolve(URL.createObjectURL(file));
      };
      request.onerror = () => reject(request.error);
    });
  } catch (err) {
    console.error('Error saving to DB:', err);
    return URL.createObjectURL(file);
  }
};

const getFileFromDB = async (key: string): Promise<string | null> => {
  try {
    const db = await initKavaMediaDB();
    return new Promise((resolve) => {
      const tx = db.transaction('media', 'readonly');
      const store = tx.objectStore('media');
      const request = store.get(key);
      request.onsuccess = () => {
        const file = request.result as File | undefined;
        if (file) {
          resolve(URL.createObjectURL(file));
        } else {
          resolve(null);
        }
      };
      request.onerror = () => resolve(null);
    });
  } catch (err) {
    console.error('Error getting from DB:', err);
    return null;
  }
};

const deleteFileFromDB = async (key: string): Promise<void> => {
  try {
    const db = await initKavaMediaDB();
    return new Promise((resolve) => {
      const tx = db.transaction('media', 'readwrite');
      const store = tx.objectStore('media');
      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => resolve();
    });
  } catch (err) {
    console.error('Error deleting from DB:', err);
  }
};

