export function applyPresetToSettings(presetId: string, currentSettings: any, templates?: Template[]): any {
  if (templates && templates.length > 0) {
    const matched = templates.find(t => t.id === presetId || t.name === presetId);
    if (matched && matched.config) {
      return {
        ...(currentSettings || {}),
        ...matched.config
      };
    }
  }

  let key = presetId;
  if (presetId === 'Classic Wedding Gold' || presetId === 'wedding') key = 'wedding';
  else if (presetId === 'Cyber Horizon 2077' || presetId === 'cyber') key = 'cyber';
  else if (presetId === 'Swiss Editorial Slate' || presetId === 'minimal_light') key = 'minimal_light';
  else if (presetId === 'Warm Retro Filmstrip' || presetId === 'elegant') key = 'elegant';
  else if (presetId === 'Corporate Minimal' || presetId === 'corporate') key = 'corporate';

  const presetValues = PRESET_SETTINGS_MAP[key] || PRESET_SETTINGS_MAP.wedding;
  return {
    ...(currentSettings || {}),
    ...presetValues
  };
}

