  const [notifSearchQuery, setNotifSearchQuery] = useState('');

  // Group notifications by time: Today, Yesterday, Earlier
  const groupedNotifications = useMemo(() => {
    const groups: {
      Today: KavaNotificationItem[];
      Yesterday: KavaNotificationItem[];
      Earlier: KavaNotificationItem[];
    } = {
      Today: [],
      Yesterday: [],
      Earlier: []
    };

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const startOfYesterday = startOfToday - 24 * 60 * 60 * 1000;

    const sorted = [...notifications].sort((a, b) => b.timestamp - a.timestamp);

    sorted.forEach(ntf => {
      const ts = ntf.timestamp || Date.now();
      if (ts >= startOfToday) {
        groups.Today.push(ntf);
      } else if (ts >= startOfYesterday) {
        groups.Yesterday.push(ntf);
      } else {
        groups.Earlier.push(ntf);
      }
    });

    return groups;
  }, [notifications]);

