  // Quick Time Presets helper for HostDashboard
  const calculateHostDeadlinePreset = (baseDate: string, mode: 'same_day' | 'plus_1_day' | 'plus_3_days' | 'plus_7_days' | 'custom'): string | null => {
    if (mode === 'custom' || !baseDate) return null;
    const parts = baseDate.split('-');
    if (parts.length !== 3) return null;
    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10);
    const day = parseInt(parts[2], 10);
    if (isNaN(year) || isNaN(month) || isNaN(day)) return null;

    const dateObj = new Date(year, month - 1, day);
    let daysToAdd = 0;
    if (mode === 'same_day') daysToAdd = 0;
    else if (mode === 'plus_1_day') daysToAdd = 1;
    else if (mode === 'plus_3_days') daysToAdd = 3;
    else if (mode === 'plus_7_days') daysToAdd = 7;

    dateObj.setDate(dateObj.getDate() + daysToAdd);

    const resYear = dateObj.getFullYear();
    const resMonth = String(dateObj.getMonth() + 1).padStart(2, '0');
    const resDay = String(dateObj.getDate()).padStart(2, '0');
    return `${resYear}-${resMonth}-${resDay}T23:59`;
  };

