  const [searchEventQuery, setSearchEventQuery] = useState<string>('');
  const [chosenTargetEvent, setChosenTargetEvent] = useState<KavaEvent | null>(null);

  const syncPresetToLocalStates = (presetSettings: any) => {
    if (!presetSettings) return;
    if (presetSettings.photoTitle !== undefined) setSettingsPhotoTitle(presetSettings.photoTitle);
    if (presetSettings.photoDesc !== undefined) setSettingsPhotoDesc(presetSettings.photoDesc);
    if (presetSettings.photoEnableFrame !== undefined) setSettingsPhotoEnableFrame(presetSettings.photoEnableFrame);
    if (presetSettings.photoFrameUrl !== undefined) setSettingsPhotoFrameUrl(presetSettings.photoFrameUrl);
    if (presetSettings.photoEnableWatermark !== undefined) setSettingsPhotoEnableWatermark(presetSettings.photoEnableWatermark);
    if (presetSettings.photoWatermarkPosition !== undefined) setSettingsPhotoWatermarkPosition(presetSettings.photoWatermarkPosition);
    if (presetSettings.photoWatermarkSize !== undefined) setSettingsPhotoWatermarkSize(presetSettings.photoWatermarkSize);
    if (presetSettings.photoWatermarkOpacity !== undefined) setSettingsPhotoWatermarkOpacity(presetSettings.photoWatermarkOpacity);
    if (presetSettings.photoFilter !== undefined) setSettingsPhotoFilter(presetSettings.photoFilter);
  };

  const handleUndoTheme = () => {
    if (originalEventSettingsBeforeTemplate) {
      setPendingThemeSettings(originalEventSettingsBeforeTemplate);
      syncPresetToLocalStates(originalEventSettingsBeforeTemplate);
    } else {
      setPendingThemeSettings(null);
    }
    setIsTemplateDirty(false);
    setActivePresetId(null);
    setPendingTemplateId(null);
    setPendingTemplateVersion(null);
    setToast({
      title: 'Theme Reverted',
      description: 'Your previous theme settings have been restored successfully.',
      items: ['Rollback complete']
    });
  };

  const handleSaveTheme = () => {
    if (pendingThemeSettings) {
      onUpdateEventSettings(selectedEvent.id, { 
        settings: pendingThemeSettings,
        ...(pendingTemplateId ? { templateId: pendingTemplateId } : {}),
        ...(pendingTemplateVersion ? { templateVersion: pendingTemplateVersion } : {})
      });
      setIsTemplateDirty(false);
      setOriginalEventSettingsBeforeTemplate(null);
      setPendingTemplateId(null);
      setPendingTemplateVersion(null);
      setToast({
        title: 'Theme Synchronized',
        description: 'Your template selection is now active and synchronized across all modules.',
        items: ['Guest Studio updated', 'Invitation Studio aligned', 'Live Screen styled']
      });
    }
  };

