    settingsVideoWatermarkSize, settingsVideoWatermarkOpacity, settingsVideoUseDefaultWatermark,
    settingsGreetingEnabled, settingsGreetingType, settingsGreetingVoiceUrl, settingsGreetingVoiceName,
    settingsGreetingVideoUrl, settingsGreetingVideoName, settingsGreetingAutoStartRecording, settingsGreetingCountdown,
    settingsGreetingNotificationTone, settingsGreetingVolume, settingsGreetingSkipEnabled, settingsGreetingReplayEnabled,
    settingsVoiceScriptPreview, settingsVoiceEnableTranscript, settingsVoiceNoiseReduction, settingsVoiceEchoCancellation,
    settingsVoiceNormalizeVolume, settingsVoiceSilenceDetection, settingsVoiceAutoTrim, settingsVoiceMaxRecordingLength,
