    setSettingsBgmVolume(selectedEvent.settings?.bgmVolume ?? 50);
    setSettingsBgmLoop(selectedEvent.settings?.bgmLoop !== false);
    setSettingsBgmFadeIn(selectedEvent.settings?.bgmFadeIn ?? 1);
    setSettingsBgmFadeOut(selectedEvent.settings?.bgmFadeOut ?? 1);
    setSettingsBgmStartTiming(selectedEvent.settings?.bgmStartTiming || 'immediately');
    setSettingsBgmAutoplay(selectedEvent.settings?.bgmAutoplay !== false);
    setSettingsEnableDucking(selectedEvent.settings?.enableDucking !== false);
