  // Collapsible sections for Live Tab
  const [showThemeMore, setShowThemeMore] = useState(false);
  const [showBgMore, setShowBgMore] = useState(false);
  const [showContentMore, setShowContentMore] = useState(false);
  const [showQrMore, setShowQrMore] = useState(false);
