                                setSettingsWishHeadline('Share Your Wishes & Blessings');
                                setSettingsVideoMaxDuration(30);
                                setSettingsVoiceMaxRecordingLength(30);
                                setSettingsPhotoCompress(true);
                                setSettingsContributionApprovalMode('auto');
