                                isPublishing
                                  ? 'bg-slate-800 text-white cursor-wait animate-pulse'
                                  : isExperienceDirty 
                                    ? 'bg-slate-900 text-white hover:bg-slate-800 shadow-sm shadow-slate-900/10' 
                                    : 'bg-slate-100 text-slate-400 cursor-not-allowed'
