                              photoWatermarkOpacity: settingsPhotoWatermarkOpacity,
                              photoFilter: settingsPhotoFilter,
                              photoCustomLutUrl: settingsPhotoCustomLutUrl,
                              photoCameraMode: settingsPhotoCameraMode,
                              photoEnableLive: settingsPhotoEnableLive,
                              photoAllowBurst: settingsPhotoAllowBurst,
                              photoCompress: settingsPhotoCompress,
