                              videoAutoStart: settingsVideoAutoStart,
                              videoAllowReplay: settingsVideoAllowReplay,
                              videoAllowSkipIntro: settingsVideoAllowSkipIntro,
                              videoOverlayLogoUrl: settingsVideoOverlayLogoUrl,
                              videoFrameUrl: settingsVideoFrameUrl,
                              videoIntroAnimation: settingsVideoIntroAnimation,
                              videoEndingScreen: settingsVideoEndingScreen,
                              videoIntroBgmUrl: settingsVideoIntroBgmUrl,
                              videoAutoDucking: settingsVideoAutoDucking,
                              videoIntroSourceType: settingsVideoIntroSourceType,
                              videoIntroFileName: settingsVideoIntroFileName,
                              videoIntroFileSize: settingsVideoIntroFileSize,
                              videoIntroDuration: settingsVideoIntroDuration,
                              videoIntroMaxSize: settingsVideoIntroMaxSize,
                              videoBgmSourceType: settingsVideoBgmSourceType,
                              videoBgmFileName: settingsVideoBgmFileName,
                              videoBgmVolume: settingsVideoBgmVolume,
