                              videoWatermarkPosition: settingsVideoWatermarkPosition,
                              videoWatermarkSize: settingsVideoWatermarkSize,
                              videoWatermarkOpacity: settingsVideoWatermarkOpacity,
                              videoUseDefaultWatermark: settingsVideoUseDefaultWatermark,
                              greetingEnabled: settingsGreetingEnabled,
                              greetingType: settingsGreetingType,
                              greetingVoiceUrl: settingsGreetingVoiceUrl,
                              greetingVoiceName: settingsGreetingVoiceName,
                              greetingVideoUrl: settingsGreetingVideoUrl,
                              greetingVideoName: settingsGreetingVideoName,
                              greetingAutoStartRecording: settingsGreetingAutoStartRecording,
                              greetingCountdown: settingsGreetingCountdown,
                              greetingNotificationTone: settingsGreetingNotificationTone,
                              greetingVolume: settingsGreetingVolume,
                              greetingSkipEnabled: settingsGreetingSkipEnabled,
                              greetingReplayEnabled: settingsGreetingReplayEnabled,
                              voiceScriptPreview: settingsVoiceScriptPreview,
                              voiceEnableTranscript: settingsVoiceEnableTranscript,
                              voiceNoiseReduction: settingsVoiceNoiseReduction,
                              voiceEchoCancellation: settingsVoiceEchoCancellation,
                              voiceNormalizeVolume: settingsVoiceNormalizeVolume,
                              voiceSilenceDetection: settingsVoiceSilenceDetection,
                              voiceAutoTrim: settingsVoiceAutoTrim,
                              voiceMaxRecordingLength: settingsVoiceMaxRecordingLength,
                              wishHeadline: settingsWishHeadline,
                              wishIntroText: settingsWishIntroText,
                              wishPlaceholder: settingsWishPlaceholder,
                              wishSuggestedPrompts: settingsWishSuggestedPrompts,
                              wishMinChars: settingsWishMinChars,
                              wishMaxChars: settingsWishMaxChars,
                              wishAllowEmojis: settingsWishAllowEmojis,
                              wishEnableHandwriting: settingsWishEnableHandwriting,
                              wishEnableSignature: settingsWishEnableSignature,
                              wishFont: settingsWishFont,
                              wishAlignment: settingsWishAlignment,
                              wishBubbleStyle: settingsWishBubbleStyle,
                              wishTheme: settingsWishTheme,
                              wishBgIllustration: settingsWishBgIllustration,
